export function credits(value: number, compact = false): string {
  if (!Number.isFinite(value)) return "₡0";
  const abs = Math.abs(value);
  if (compact && abs >= 1_000_000_000) return `₡${(value / 1_000_000_000).toFixed(2)}B`;
  if (compact && abs >= 1_000_000) return `₡${(value / 1_000_000).toFixed(2)}M`;
  if (compact && abs >= 10_000) return `₡${(value / 1_000).toFixed(1)}K`;
  return `₡${Math.round(value).toLocaleString("en-US")}`;
}

export function number(value: number, digits = 0): string {
  return value.toLocaleString("en-US", {
    minimumFractionDigits: digits,
    maximumFractionDigits: digits,
  });
}

export function compact(value: number, digits = 1): string {
  const abs = Math.abs(value);
  if (abs >= 1_000_000_000) return `${(value / 1_000_000_000).toFixed(digits)}B`;
  if (abs >= 1_000_000) return `${(value / 1_000_000).toFixed(digits)}M`;
  if (abs >= 1_000) return `${(value / 1_000).toFixed(digits)}K`;
  return value.toFixed(digits);
}

export function price(value: number): string {
  if (value >= 1000) return value.toLocaleString("en-US", { maximumFractionDigits: 0 });
  if (value >= 1) return value.toFixed(2);
  if (value >= 0.01) return value.toFixed(4);
  return value.toFixed(6);
}

export function pct(value: number, digits = 2): string {
  return `${value >= 0 ? "+" : ""}${value.toFixed(digits)}%`;
}

export function initials(name: string): string {
  return name
    .split(/\s+/)
    .slice(0, 2)
    .map((p) => p[0]?.toUpperCase() ?? "")
    .join("");
}

export function timeAgo(day: number, currentDay: number): string {
  const delta = Math.max(0, currentDay - day);
  if (delta === 0) return "now";
  if (delta === 1) return "1d";
  if (delta < 7) return `${delta}d`;
  return `${Math.ceil(delta / 7)}w`;
}

export function heatLabel(heat: number): string {
  if (heat < 20) return "Invisible";
  if (heat < 40) return "Noticed";
  if (heat < 60) return "Tracked";
  if (heat < 80) return "Hunted";
  return "Burned";
}

"use client";

import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import * as engine from "@/lib/engine";
import { ARCHETYPES, createInitialState } from "@/lib/seed";
import type { ActionResult, Archetype, GameState, Toast, WorldEvent } from "@/lib/types";

const STORAGE_KEY = "omnilife-syndicate-save-v1";
const BASE_TICK_MS = 9000;

interface GameContextValue {
  state: GameState | null;
  hydrated: boolean;
  aiMode: "grok" | "local" | "checking";
  aiBusy: boolean;
  startGame: (profile: { name: string; handle: string; email: string; archetype: Archetype }) => void;
  resetGame: () => void;
  setSpeed: (speed: GameState["speed"]) => void;
  dismissToast: (id: string) => void;
  act: (fn: (state: GameState) => ActionResult) => void;
  summonEvent: () => Promise<void>;
}

const GameContext = createContext<GameContextValue | null>(null);

function safeLoad(): GameState | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as GameState;
    if (parsed?.version !== 1 || !parsed.player || !Array.isArray(parsed.tokens)) return null;
    return parsed;
  } catch {
    return null;
  }
}

function addToast(state: GameState, toast: Omit<Toast, "id">): GameState {
  const item: Toast = {
    ...toast,
    id: `toast-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
  };
  return { ...state, toasts: [...state.toasts.slice(-3), item] };
}

export function GameProvider({ children }: { children: React.ReactNode }) {
  const [state, setState] = useState<GameState | null>(null);
  const [hydrated, setHydrated] = useState(false);
  const [aiMode, setAiMode] = useState<"grok" | "local" | "checking">("checking");
  const [aiBusy, setAiBusy] = useState(false);
  const stateRef = useRef<GameState | null>(null);
  const lastEventRef = useRef<string | null>(null);

  useEffect(() => {
    const loaded = safeLoad();
    const initial = loaded ?? createInitialState();
    setState(initial);
    setHydrated(true);
    if (loaded) lastEventRef.current = loaded.events[0]?.id ?? null;
  }, []);

  useEffect(() => {
    stateRef.current = state;
  }, [state]);

  useEffect(() => {
    if (!hydrated || !state) return;
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch {
      /* storage can be full or disabled; the session still works */
    }
  }, [state, hydrated]);

  useEffect(() => {
    fetch("/api/world-engine")
      .then((r) => r.json())
      .then((data: { configured?: boolean }) => setAiMode(data.configured ? "grok" : "local"))
      .catch(() => setAiMode("local"));
  }, []);

  // Server-side admin allowlist check. This unlocks the fictional God Mode UI;
  // it is not an authentication system for a production deployment.
  useEffect(() => {
    if (!state?.started || state.adminUnlocked || !state.player.email) return;
    let cancelled = false;
    fetch("/api/admin/unlock", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: state.player.email }),
    })
      .then((r) => (r.ok ? r.json() : { admin: false }))
      .then((data: { admin?: boolean }) => {
        if (cancelled || !data.admin) return;
        setState((prev) => (prev ? { ...prev, adminUnlocked: true } : prev));
      })
      .catch(() => undefined);
    return () => {
      cancelled = true;
    };
  }, [state?.started, state?.adminUnlocked, state?.player.email]);

  // World clock
  useEffect(() => {
    if (!state?.started || state.speed === 0) return;
    const ms = BASE_TICK_MS / state.speed;
    const timer = window.setInterval(() => {
      setState((prev) => (prev && prev.started ? engine.tickWorld(prev) : prev));
    }, ms);
    return () => window.clearInterval(timer);
  }, [state?.started, state?.speed]);

  // Surface fresh world events as toasts.
  useEffect(() => {
    if (!state?.events.length) return;
    const latest = state.events[0];
    if (!lastEventRef.current) {
      lastEventRef.current = latest.id;
      return;
    }
    if (latest.id !== lastEventRef.current) {
      lastEventRef.current = latest.id;
      setState((prev) =>
        prev
          ? addToast(prev, {
              kind: latest.severity === "critical" || latest.severity === "black-swan" ? "warning" : "info",
              title: `World event · ${latest.title}`,
              message: latest.description.slice(0, 150),
            })
          : prev,
      );
    }
  }, [state?.events]);

  // Auto-dismiss toasts
  useEffect(() => {
    if (!state?.toasts.length) return;
    const timers = state.toasts.map((toast) =>
      window.setTimeout(() => {
        setState((prev) => (prev ? { ...prev, toasts: prev.toasts.filter((t) => t.id !== toast.id) } : prev));
      }, 5200),
    );
    return () => timers.forEach((t) => window.clearTimeout(t));
  }, [state?.toasts]);

  const startGame = useCallback(
    (profile: { name: string; handle: string; email: string; archetype: Archetype }) => {
      const next = createInitialState(profile);
      next.started = true;
      lastEventRef.current = next.events[0]?.id ?? null;
      setState(next);
    },
    [],
  );

  const resetGame = useCallback(() => {
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch {
      /* ignore */
    }
    const fresh = createInitialState();
    setState(fresh);
  }, []);

  const setSpeed = useCallback((speed: GameState["speed"]) => {
    setState((prev) => (prev ? { ...prev, speed } : prev));
  }, []);

  const dismissToast = useCallback((id: string) => {
    setState((prev) => (prev ? { ...prev, toasts: prev.toasts.filter((t) => t.id !== id) } : prev));
  }, []);

  const act = useCallback((fn: (state: GameState) => ActionResult) => {
    setState((prev) => {
      if (!prev) return prev;
      const result = fn(prev);
      return result.toast ? addToast(result.state, result.toast) : result.state;
    });
  }, []);

  const summonEvent = useCallback(async () => {
    const snapshot = stateRef.current;
    if (!snapshot) return;
    setAiBusy(true);
    try {
      const response = await fetch("/api/world-engine", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          day: snapshot.day,
          economy: Math.round(snapshot.economy),
          regulation: Math.round(snapshot.government.regulation),
          playerNetWorth: Math.round(snapshot.player.netWorthHistory.at(-1)?.value ?? 0),
          topTokens: snapshot.tokens
            .filter((t) => !t.rugged)
            .slice(0, 5)
            .map((t) => ({ symbol: t.symbol, price: t.price, change: t.change24h })),
          activeEvents: snapshot.events.slice(0, 3).map((e) => e.title),
          headlines: snapshot.wire.slice(0, 4).map((p) => p.body),
        }),
      });
      if (!response.ok) throw new Error("World engine unavailable");
      const data = (await response.json()) as { event: WorldEvent; mode: "grok" | "local" };
      setAiMode(data.mode);
      setState((prev) => {
        if (!prev) return prev;
        const next = structuredClone(prev);
        engine.applyEventShock(next, { ...data.event, source: data.mode === "grok" ? "grok" : "system" });
        return addToast(next, {
          kind: data.mode === "grok" ? "info" : "warning",
          title: data.event.title,
          message:
            data.mode === "grok"
              ? `Grok World Engine · ${data.event.description.slice(0, 130)}`
              : `Local simulation fallback · ${data.event.description.slice(0, 130)}`,
        });
      });
    } catch {
      setAiMode("local");
      setState((prev) =>
        prev
          ? addToast(prev, {
              kind: "error",
              title: "World engine unreachable",
              message: "The local simulation is still running. Check GROK_API_KEY to enable live AI events.",
            })
          : prev,
      );
    } finally {
      setAiBusy(false);
    }
  }, []);

  const value = useMemo<GameContextValue>(
    () => ({
      state,
      hydrated,
      aiMode,
      aiBusy,
      startGame,
      resetGame,
      setSpeed,
      dismissToast,
      act,
      summonEvent,
    }),
    [state, hydrated, aiMode, aiBusy, startGame, resetGame, setSpeed, dismissToast, act, summonEvent],
  );

  return <GameContext.Provider value={value}>{children}</GameContext.Provider>;
}

export function useGame(): GameContextValue {
  const ctx = useContext(GameContext);
  if (!ctx) throw new Error("useGame must be used inside GameProvider");
  return ctx;
}

export function useProfileLabel(state: GameState): string {
  return `${ARCHETYPES[state.player.archetype].label}`;
}

import { NextResponse } from "next/server";
import type { WorldEvent } from "@/lib/types";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const FALLBACK_EVENTS: Array<Omit<WorldEvent, "id" | "day" | "expires" | "source">> = [
  {
    title: "Liquidity mirage",
    description:
      "A prime brokerage quietly tightened margin across the city. Leveraged players are learning that collateral is a story told by someone with more cash.",
    category: "market",
    severity: "major",
    pulse: -5,
    sentiment: -7,
    crime: 2,
    regulation: 3,
  },
  {
    title: "The regulator's inbox",
    description:
      "A whistleblower dumped 14,000 internal compliance emails. Half the city's licenses are now negotiable, and the other half are radioactive.",
    category: "policy",
    severity: "critical",
    pulse: -6,
    sentiment: -4,
    crime: 5,
    regulation: 11,
  },
  {
    title: "Fiber futures spike",
    description:
      "A hyperscaler booked every available wavelength for the next quarter. Bandwidth spot prices doubled before breakfast.",
    category: "infrastructure",
    severity: "major",
    pulse: 4,
    sentiment: 3,
    crime: 0,
    regulation: 1,
  },
  {
    title: "Narrative overflow",
    description:
      "A coordinated bot swarm pushed three unrelated tokens to the top of every feed. Retail is calling it a movement. The order books call it exit liquidity.",
    category: "media",
    severity: "minor",
    pulse: 7,
    sentiment: 6,
    crime: 1,
    regulation: 0,
  },
  {
    title: "Night court verdict",
    description:
      "A sealed hearing acquitted a syndicate lieutenant on all counts. The judge's re-election fund received an anonymous transfer within the hour.",
    category: "crime",
    severity: "major",
    pulse: -2,
    sentiment: -5,
    crime: 8,
    regulation: -2,
  },
  {
    title: "Orbital data arbitrage",
    description:
      "A private satellite constellation began selling millisecond advantage to three trading desks. Latency is now a luxury good.",
    category: "market",
    severity: "major",
    pulse: 6,
    sentiment: 2,
    crime: 0,
    regulation: 2,
  },
];

function fallbackEvent(seed: number): WorldEvent {
  const template = FALLBACK_EVENTS[Math.abs(seed) % FALLBACK_EVENTS.length];
  const now = Math.floor(Date.now() / 1000);
  return {
    ...template,
    id: `fallback-${now}-${seed % 997}`,
    day: 0,
    expires: 999_999,
    source: "system",
  };
}

const ALLOWED_CATEGORIES = new Set(["market", "policy", "crime", "media", "infrastructure", "ai"]);
const ALLOWED_SEVERITIES = new Set(["minor", "major", "critical", "black-swan"]);

function sanitize(raw: unknown, mode: "grok" | "local"): WorldEvent | null {
  if (!raw || typeof raw !== "object") return null;
  const obj = raw as Record<string, unknown>;
  if (typeof obj.title !== "string" || typeof obj.description !== "string") return null;
  const category = typeof obj.category === "string" && ALLOWED_CATEGORIES.has(obj.category) ? obj.category : "market";
  const severity =
    typeof obj.severity === "string" && ALLOWED_SEVERITIES.has(obj.severity) ? obj.severity : "major";
  const num = (value: unknown, fallback: number) =>
    typeof value === "number" && Number.isFinite(value) ? Math.max(-20, Math.min(20, value)) : fallback;
  return {
    id: `event-${Date.now().toString(36)}`,
    title: obj.title.slice(0, 90),
    description: obj.description.slice(0, 480),
    category: category as WorldEvent["category"],
    severity: severity as WorldEvent["severity"],
    pulse: num(obj.pulse, -3),
    sentiment: num(obj.sentiment, -4),
    crime: num(obj.crime, 1),
    regulation: num(obj.regulation, 2),
    day: 0,
    expires: 999_999,
    source: mode === "grok" ? "grok" : "system",
  };
}

// Lightweight in-memory rate limit. Serverless instances reset, but this stops
// accidental request loops from burning paid API credits.
const hits = new Map<string, { count: number; reset: number }>();
function allowed(ip: string): boolean {
  const now = Date.now();
  const entry = hits.get(ip);
  if (!entry || now > entry.reset) {
    hits.set(ip, { count: 1, reset: now + 60_000 });
    return true;
  }
  if (entry.count >= 8) return false;
  entry.count += 1;
  return true;
}

export async function GET() {
  return NextResponse.json({
    configured: Boolean(process.env.GROK_API_KEY || process.env.XAI_API_KEY),
    model: process.env.GROK_MODEL || "grok-4",
    capabilities: ["world-events", "npc-masterminds", "market-narrative"],
  });
}

export async function POST(request: Request) {
  const ip = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || "local";
  if (!allowed(ip)) {
    return NextResponse.json({ error: "Rate limit exceeded. The city needs a moment." }, { status: 429 });
  }

  let body: Record<string, unknown> = {};
  try {
    body = (await request.json()) as Record<string, unknown>;
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const key = process.env.GROK_API_KEY || process.env.XAI_API_KEY;
  const day = typeof body.day === "number" ? Math.round(body.day) : 1;

  if (!key) {
    const event = fallbackEvent(day + Date.now());
    event.day = day;
    event.expires = day + 4;
    return NextResponse.json({
      mode: "local",
      event,
      note: "GROK_API_KEY is not configured. Deterministic world engine used.",
    });
  }

  const system = `You are the autonomous World Engine for OmniLife: The Syndicate, a cyber-noir economic MMO.
Generate ONE plausible, specific macroeconomic or political shock based on the live server state.
Rules:
- Output strict JSON only, no markdown, no commentary.
- Shape: {"title":string,"description":string,"category":"market"|"policy"|"crime"|"media"|"infrastructure"|"ai","severity":"minor"|"major"|"critical"|"black-swan","pulse":number,"sentiment":number,"crime":number,"regulation":number}
- "description" must be 2-3 sentences, concrete, mention at least one named entity from the state, and imply a gameplay consequence.
- pulse/sentiment are market/social effects from -20 to 20. crime/regulation are 0 to 20.
- Never use placeholders, generic filler, or fourth-wall references. The city is real to its inhabitants.`;

  const user = `LIVE SERVER STATE
Day: ${day}
Economy index: ${body.economy ?? 50}/100
Regulation: ${body.regulation ?? 50}/100
Player net worth: ${body.playerNetWorth ?? 0}
Top tokens: ${JSON.stringify(body.topTokens ?? [])}
Active events: ${JSON.stringify(body.activeEvents ?? [])}
Recent Wire headlines: ${JSON.stringify(body.headlines ?? [])}

Invent the next world event. Escape the current narrative rather than repeating it.`;

  try {
    const response = await fetch("https://api.x.ai/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${key}`,
      },
      body: JSON.stringify({
        model: process.env.GROK_MODEL || "grok-4",
        temperature: 0.95,
        max_tokens: 700,
        response_format: { type: "json_object" },
        messages: [
          { role: "system", content: system },
          { role: "user", content: user },
        ],
      }),
      signal: AbortSignal.timeout(20_000),
    });

    if (!response.ok) {
      const detail = await response.text();
      console.error("Grok world engine error", response.status, detail.slice(0, 300));
      const event = fallbackEvent(day + 3);
      event.day = day;
      event.expires = day + 4;
      return NextResponse.json({ mode: "local", event, note: "Grok call failed; local engine used." });
    }

    const payload = (await response.json()) as {
      choices?: Array<{ message?: { content?: string } }>;
    };
    const content = payload.choices?.[0]?.message?.content ?? "";
    let parsed: unknown;
    try {
      parsed = JSON.parse(content);
    } catch {
      const match = content.match(/\{[\s\S]*\}/);
      parsed = match ? JSON.parse(match[0]) : null;
    }
    const event = sanitize(parsed, "grok");
    if (!event) {
      const fallback = fallbackEvent(day + 7);
      fallback.day = day;
      fallback.expires = day + 4;
      return NextResponse.json({ mode: "local", event: fallback, note: "Malformed model output; local engine used." });
    }
    event.day = day;
    event.expires = day + 5;
    return NextResponse.json({ mode: "grok", event });
  } catch (error) {
    console.error("Grok world engine exception", error);
    const event = fallbackEvent(day + 11);
    event.day = day;
    event.expires = day + 4;
    return NextResponse.json({ mode: "local", event, note: "Network failure; local engine used." });
  }
}

import { NextResponse } from "next/server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// Demo identity gate for the fictional God Mode terminal.
// For a real deployment, replace this with Supabase Auth + a server-signed
// role claim. An email allowlist is not authentication.
const hits = new Map<string, { count: number; reset: number }>();

function allow(ip: string): boolean {
  const now = Date.now();
  const entry = hits.get(ip);
  if (!entry || now > entry.reset) {
    hits.set(ip, { count: 1, reset: now + 60_000 });
    return true;
  }
  if (entry.count >= 10) return false;
  entry.count += 1;
  return true;
}

export async function POST(request: Request) {
  const ip = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || "local";
  if (!allow(ip)) return NextResponse.json({ admin: false, error: "Rate limited" }, { status: 429 });

  let email = "";
  try {
    const body = (await request.json()) as { email?: unknown };
    email = typeof body.email === "string" ? body.email.trim().toLowerCase() : "";
  } catch {
    return NextResponse.json({ admin: false }, { status: 400 });
  }
  if (!email) return NextResponse.json({ admin: false }, { status: 400 });

  const raw = process.env.ADMIN_EMAILS || process.env.NEXT_PUBLIC_ADMIN_EMAILS || "mirajx132@gmail.com";
  const allowed = raw
    .split(",")
    .map((value) => value.trim().toLowerCase())
    .filter(Boolean);
  if (!allowed.includes(email)) {
    return NextResponse.json({ admin: false }, { status: 403 });
  }
  return NextResponse.json({ admin: true, scope: "world-override" });
}

