@import "tailwindcss";

@theme {
  --color-void: #060807;
  --color-abyss: #080b09;
  --color-panel: #0b100d;
  --color-panel-2: #0f1511;
  --color-line: #1c261f;
  --color-line-bright: #2b3a2f;
  --color-ink: #e9f1e9;
  --color-muted: #819085;
  --color-dim: #556158;
  --color-acid: #c9ff4d;
  --color-mint: #63f7c3;
  --color-ember: #ffb454;
  --color-danger: #ff625c;
  --color-ice: #8fa8ff;
  --font-sans: "Inter", "Segoe UI", ui-sans-serif, system-ui, -apple-system, sans-serif;
