  background:
    linear-gradient(180deg, rgba(20, 28, 22, 0.66) 0%, rgba(9, 13, 10, 0.88) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.025),
    0 18px 60px -30px rgba(0, 0, 0, 0.9);
  border-radius: 14px;
  backdrop-filter: blur(14px);
}

.panel-flat {
  border: 1px solid rgba(43, 58, 47, 0.45);
