                    <span
                      className={`mono rounded px-1.5 py-0.5 text-[8px] uppercase ${
                        bank.status === "stable" ? "bg-mint/10 text-mint" : bank.status === "strained" ? "bg-ember/10 text-ember" : "bg-danger/10 text-danger"
